("mnemonic","GREEK ORIGIN",[("mnēmē","memory","記憶","a glowing brain with a string tied around a finger"),("-ikos","relating to","與…有關的","a link chain")],("relating to memory → a trick that helps you remember","記憶術；助記方法"),"a student sings a silly rainbow song \"ROY G BIV\" while colorful letters float into her head and stick there.","A rhyme, a song, a trick to keep,","Mnemonic memories run deep."),
("sonorous","LATIN ORIGIN",[("sonare","to sound","發出聲音","a big ringing bell"),("-orus","full of","充滿…的","a full jar")],("full of sound → deep, rich, and loud","聲音宏亮的；渾厚的"),"a choir boy with a deep booming voice sings so richly that the music notes fill the whole school hall.","Deep and rich, the voice rings round,","Sonorous fills the hall with sound."),
("admonish","LATIN ORIGIN",[("ad-","to, toward","朝向","an arrow pointing right"),("monere","to warn, remind","警告；提醒","a yellow warning sign")],("give a warning to → gently but firmly scold","告誡；勸誡"),"a kind librarian raises one finger and gently warns two boys who are tossing a paper airplane in the library.","A gentle word, a finger raised,","Admonish now, be wise, not dazed."),
("paradigm","GREEK ORIGIN",[("para-","beside","在旁邊","two figures standing side by side"),("deiknynai","to show","展示","a pointing hand")],("shown side by side as a pattern → a model or example","典範；範例"),"a teacher holds up a perfect model volcano beside the class's projects, and students copy its pattern.","Show the model, set the way,","Paradigm leads us every day."),
