("vindicate","LATIN ORIGIN",[("vis","force, power","力量","a flexing arm"),("dicere","to say, declare","說；宣告","a speech bubble")],("declare with force → prove someone right or innocent","證明…正確；洗清嫌疑"),"a girl wrongly blamed for a broken vase cheers as a video replay shows the cat knocked it over.","The truth comes out, my name is clear,","Vindicate! I'm cheered right here."),
("bucolic","GREEK ORIGIN",[("bous","cow, ox","牛","a smiling cow"),("kolos","herder, tender","放牧者","a shepherd's staff")],("of the cowherd → peaceful country life","田園的；鄉村風味的"),"kids on a school field trip picnic on a green hill with grazing cows, a red barn, and a sparkling stream.","Cows and meadows, skies so blue,","Bucolic peace is calling you."),
("ostracize","GREEK ORIGIN",[("ostrakon","pottery shard, shell","陶片","a broken pottery piece with a name scratched on it"),("-izein","to do, to make","使…；做","a gear")],("vote with pottery shards to banish → shut someone out","排擠；放逐"),"ancient Greek citizens drop pottery shards in a jar to vote, while one man walks sadly away out of the city gate.","Write the name, then send away,","Ostracize: you cannot stay."),
("plethora","GREEK ORIGIN",[("plēthōrē","fullness (from plēthein: to be full)","充滿；過滿","a jar overflowing")],("fullness → far too much of something","過多；過剩"),"a kid opens a closet and a plethora of plush toys tumbles out and fills the whole bedroom.","Much too much, the closet's packed,","Plethora of toys: a fact!"),
("proclivity","LATIN ORIGIN",[("pro-","forward","向前","a forward arrow"),("clivus","slope, hill","斜坡","a tilted hill")],("sloping forward → a natural tendency","傾向；癖好"),"a boy on a gentle hill keeps rolling down toward the snack table as if pulled there by the slope.","Down the slope my feet will go,","Proclivity: I'm leaning so."),
